using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "NonNormalChantingCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/NonNormalChantingCustomDescription", order = 0)]
public class NonNormalChantingCustomDescription : CustomBattleActionDescription
{
	private const string chantingID = "Chanting_D";

	private const string gainAdditionalEffectID = "GainAdditionalEffect";

	private const string gainAdditionalEffectForEachID = "GainAdditionalEffectForEach";

	[SerializeField]
	private PurifyCorruptCustomDescription purifyCorruptCustomDescription;

	[SerializeField]
	private bool appendActionDescription;

	[SerializeField]
	private bool appendActionDescriptionWithNewParagraph;

	[Header("Additional Chanting")]
	[SerializeField]
	private bool gainAdditionalChanting;

	[SerializeField]
	[ShowIf("gainAdditionalChanting")]
	private int fixedAdditionalChanting;

	[SerializeField]
	private bool gainAdditionalChantingForEach;

	[SerializeField]
	[ShowIf("gainAdditionalChantingForEach")]
	private int fixedAdditionalChantingForEach;

	public string ChantingID => "Chanting_D";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ChantingAction chantingAction = battleAction as ChantingAction;
		string chantingDescriptionLocalized = GetChantingDescriptionLocalized(battleAction);
		string text = "";
		if (gainAdditionalChanting)
		{
			text = "\n" + Smart.Format(base.localizationManager.GetLocalizedString("GainAdditionalEffect"), (fixedAdditionalChanting > 0) ? fixedAdditionalChanting : GetAmountWithoutEquation(amountModified), chantingAction.ChantingEffect.GetEffectName());
		}
		string text2 = "";
		if (gainAdditionalChantingForEach)
		{
			text2 = "\n" + Smart.Format(base.localizationManager.GetLocalizedString("GainAdditionalEffectForEach"), (fixedAdditionalChantingForEach > 0) ? fixedAdditionalChantingForEach.ToString() : GetAmountWithUnlockablesModification(GetAmountWithoutEquation(amountModified).ToString()), chantingAction.ChantingEffect.GetEffectName(), GetRawLocalizedDescription(battleAction));
		}
		string text3 = "";
		if (appendActionDescription && !gainAdditionalChantingForEach)
		{
			text3 = (appendActionDescriptionWithNewParagraph ? "\n" : base.localizationManager.GetLocalizedSpace()) + Smart.Format(GetRawLocalizedDescription(battleAction), GetFinalAmountWithoutEquation(amountModified));
		}
		return chantingDescriptionLocalized + text + text2 + text3;
	}

	public string GetChantingDescriptionLocalized(BattleAction battleAction)
	{
		string localizedString = base.localizationManager.GetLocalizedString("Chanting_D");
		return Smart.Format(purifyCorruptCustomDescription.GetTargetCorruptPurifyLocalized(battleAction), localizedString);
	}
}
